    used_codes = {}

    for component in SalaryComponent.objects.order_by("structure_id", "created_at", "id"):
        base = re.sub(r"[^A-Z0-9]+", "_", component.name.strip().upper()).strip("_") or "COMPONENT"
        base = base[:40]
        key = (component.structure_id, base)
        suffix = used_codes.get(key, 1)
        code = base if suffix == 1 else f"{base[:40 - len(str(suffix)) - 1]}_{suffix}"
        while SalaryComponent.objects.filter(structure_id=component.structure_id, code=code).exclude(pk=component.pk).exists():
            suffix += 1
            code = f"{base[:40 - len(str(suffix)) - 1]}_{suffix}"
        used_codes[key] = suffix + 1
        component.code = code
        component.save(update_fields=["code"])

        SalaryComponentRevision.objects.create(
            component=component,
            effective_from=date(1900, 1, 1),
            configuration={
                "code": code,
                "name": component.name,
                "component_type": component.component_type,
                "calculation_type": component.calculation_type,
                "value": str(component.value),
                "is_taxable": component.is_taxable,
                "is_active": component.is_active,
                "order": component.order,
            },
        )


